import {allowedValuesValidator} from './allowed-values-validator';

// all tests were entirely generated by claude. Some unnecessary tests got removed by me
describe('allowedValuesValidator', () => {
    const validator = allowedValuesValidator(['380', '381', '83', '84']);

    it('accepts the first allowed value', () => {
        expect(validator('380')).toBeNull();
    });

    it('accepts the last allowed value', () => {
        expect(validator('84')).toBeNull();
    });

    it('rejects a value that is not in the list', () => {
        expect(validator('382')).toEqual(expect.any(String));
    });

    it('rejects an empty string', () => {
        expect(validator('')).toEqual(expect.any(String));
    });

    it('rejects a value with leading space', () => {
        expect(validator(' 380')).toEqual(expect.any(String));
    });

    it('rejects a value with trailing space', () => {
        expect(validator('380 ')).toEqual(expect.any(String));
    });

    it('rejects a value that only partly matches', () => {
        expect(validator('38')).toEqual(expect.any(String));
    });

    it('is case sensitive', () => {
        const letters = allowedValuesValidator(['S', 'T']);
        expect(letters('s')).toEqual(expect.any(String));
    });

    it('lists the allowed values in the error message', () => {
        expect(validator('999')).toContain('380, 381, 83, 84');
    });

    it('rejects everything for an empty list of allowed values', () => {
        expect(allowedValuesValidator([])('1')).toEqual(expect.any(String));
    });
});